char * IperfMessage_GetPointer(uint16_t idx)
{
  return (char *) (message + (idx % IPERF_MESSAGE_LENGTH));
}

bool IperfMessage_CheckForEquality(char *buffer)
{
  uint16_t originalMessageSum;
  uint16_t bufferMessageSum;
  for (int i = 0; i < IPERF_MESSAGE_LENGTH; i++)
  {
    originalMessageSum += * ((uint8_t *) IperfMessage_GetPointer(i));
    bufferMessageSum += (uint8_t) buffer[i];
  }
  return (originalMessageSum == bufferMessageSum);
}
